var unified = {};
unified.source = "TTNV3";


if('join_accept' in msg.payload){
    return;
}

// unified.dateTime = msg.collectedTime;
var tzoffset = (new Date()).getTimezoneOffset() * 60000; //offset in milliseconds
var dateTime = (new Date(Date.now() - tzoffset)).toISOString().slice(0, 19).replace('T', ' ');
unified.dateTime = dateTime;

unified.devID = msg.payload.end_device_ids.device_id;
unified.appEUI = msg.payload.end_device_ids.join_eui;
unified.devEUI = msg.payload.end_device_ids.dev_eui;
unified.appID = msg.payload.end_device_ids.application_ids.application_id;
if(typeof msg.payload.uplink_message.f_cnt !== 'undefined') {
    unified.fcnt = msg.payload.uplink_message.f_cnt
}else{
    unified.fcnt = 0;
}

unified.port = msg.payload.uplink_message.f_port;
unified.devAddr = msg.payload.end_device_ids.dev_addr;
unified.frequency = parseInt(msg.payload.uplink_message.settings.frequency)/1000000;

unified.sf = msg.payload.uplink_message.settings.data_rate.lora.spreading_factor
// unified.sf = "";

unified.payload = {};
unified.payload.buffer = Buffer.from(msg.payload.uplink_message.frm_payload, 'base64');
unified.payload.size = Buffer.byteLength(msg.payload.uplink_message.frm_payload);
unified.payload.base64 = msg.payload.uplink_message.frm_payload;
unified.payload.decoded = {};
unified.payload.decoded = msg.payload.uplink_message.decoded_payload;

unified.metaData = {};
unified.metaData.gatewayCount = msg.payload.uplink_message.rx_metadata.length;
unified.metaData.gateways = [];
for (var i=0 ; i < unified.metaData.gatewayCount ; i++) {
    var data = {};
    data.name = msg.payload.uplink_message.rx_metadata[i].gateway_ids.gateway_id;

    if(typeof msg.payload.uplink_message.rx_metadata[i].gateway_ids.eui !== 'undefined') {
        data.id = msg.payload.uplink_message.rx_metadata[i].gateway_ids.eui;
    } else {
        data.id = 0;
    }

    data.rssi = msg.payload.uplink_message.rx_metadata[i].rssi;
    data.snr = msg.payload.uplink_message.rx_metadata[i].snr;

    if(typeof msg.payload.uplink_message.rx_metadata[i].location !== 'undefined') {
        data.lat = msg.payload.uplink_message.rx_metadata[i].location.latitude;
        data.lon = msg.payload.uplink_message.rx_metadata[i].location.longitude;
        data.height = msg.payload.uplink_message.rx_metadata[i].location.altitude;
    } else {
        data.lat = 0;
        data.lon = 0;
        data.height = 0;
    }

    unified.metaData.gateways.push(data);
}

return unified;

//var device = msg.devID;
var device = msg.appID;
var deviceType = 0;

// check to prevent payloads from processing that are empty.
if (typeof msg.payload.decoded === 'undefined') {
    return;
}

// Process available payload topics
if (typeof msg.payload.decoded.flowMeter !== 'undefined') {
    msg.payload.flowMeter = msg.payload.decoded.flowMeter;
}

if (typeof msg.payload.decoded.batteryVoltage !== 'undefined') {
    msg.payload.batteryVoltage = msg.payload.decoded.batteryVoltage;
}

if (typeof msg.payload.decoded.levelMeter !== 'undefined') {
    msg.payload.levelMeter = msg.payload.decoded.levelMeter;
}

msg.payload.database = "RaintankNetwork";

const d = new Date();
d.setMinutes(d.getMinutes() - d.getTimezoneOffset());

msg.payload.datetime = d
    .toISOString()
    .slice(0, 19)
    .replace('T', ' ');

msg.payload.devID = msg.devID;
msg.payload.devEUI = msg.devEUI;

// --------------------------------------------------
// LoRaWAN radio metadata
// --------------------------------------------------

if (typeof msg.metaData !== 'undefined') {

msg.payload.gatewayCount = msg.metaData.gatewayCount || 0;

    if (msg.metaData &&
        msg.metaData.gateways) {

        msg.gatewayCount =
            msg.metaData.gatewayCount;

        msg.payload.radioMetadata =
            msg.metaData.gateways.map(gw => ({
                gateway_name: gw.name,
                gateway_eui: gw.id,
                rssi: gw.rssi,
                snr: gw.snr,
                latitude: gw.lat,
                longitude: gw.lon,
                height: gw.height
            }));
    }

    return msg;
}

return msg;
